19	  assert.equal(normalizeDelivery('push'), 'auto-merge');   // legacy alias
20	  assert.equal(normalizeDelivery('review'), 'review');
21	  assert.equal(normalizeDelivery('pr'), 'review');         // legacy alias
22	  assert.equal(normalizeDelivery(' review '), 'review');   // trimmed
23	  assert.equal(normalizeDelivery('bogus'), null);
24	  assert.equal(normalizeDelivery(undefined), null);
