44	test('resolveDelivery passes a stated intent through untouched — legacy aliases included', () => {
45	  assert.deepEqual(resolveDelivery('review'), { delivery: 'review', materialize: false });
46	  assert.deepEqual(resolveDelivery('auto-merge'), { delivery: 'auto-merge', materialize: false });
47	  assert.deepEqual(resolveDelivery('pr'), { delivery: 'review', materialize: false });
48	  assert.deepEqual(resolveDelivery('push'), { delivery: 'auto-merge', materialize: false });
49	  assert.deepEqual(resolveDelivery('auto'), { delivery: 'auto-merge', materialize: false });
50	});
