52	test('resolveDelivery still fails the run on an unrecognized value — never a silent default', () => {
53	  assert.deepEqual(resolveDelivery('bogus'), { delivery: null, materialize: false });
54	  assert.deepEqual(resolveDelivery('merge'), { delivery: null, materialize: false });
